// Copies deployed addresses and ABIs from the contracts workspace into lib/.
// Generated files are committed, so builds work even where ../contracts/out is absent (e.g. Vercel).
import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const deployments = join(root, "..", "deployments", "base-sepolia.json");
const out = join(root, "..", "contracts", "out");
const broadcast = join(root, "..", "contracts", "broadcast", "DeployTestnet.s.sol", "84532", "run-latest.json");

if (!existsSync(deployments) || !existsSync(out)) {
  console.log("[sync] contracts workspace not found; using committed lib/addresses.ts and lib/abis/*");
  process.exit(0);
}

const d = JSON.parse(readFileSync(deployments, "utf8"));
const markets = Object.keys(d).filter((k) => d[k] && typeof d[k] === "object" && d[k].vault);

// First block of the deployment, so event scans don't start at genesis.
let deployBlock = 0n;
if (existsSync(broadcast)) {
  const b = JSON.parse(readFileSync(broadcast, "utf8"));
  const blocks = (b.receipts ?? []).map((r) => BigInt(r.blockNumber));
  if (blocks.length) deployBlock = blocks.reduce((a, x) => (x < a ? x : a));
}

const header = "// Generated by scripts/sync-contracts.mjs. Do not edit by hand.\n";
const marketSrc = markets
  .map((m) => {
    const x = d[m];
    return `  ${m}: {
    stock: "${x.stock}",
    vault: "${x.vault}",
    router: "${x.router}",
    pieces: [${x.pieces.map((p) => `"${p}"`).join(", ")}],
    symbols: [${x.symbols.map((s) => `"${s}"`).join(", ")}],
  },`;
  })
  .join("\n");

const addr = `${header}import type { Address } from "viem";

export const CHAIN_ID = ${d.chainId} as const;

export const ADDRESSES = {
  faucet: "${d.faucet}",
  policyRegistry: "${d.policyRegistry}",
  poolManager: "${d.poolManager}",
  stateView: "0x571291b572ed32ce6751a2cb2486ebee8defb9b4",
  quoter: "0x5e6B8B8AFA7e5CEF6C09dd2A67aBA9FB12C75623",
} as const satisfies Record<string, Address>;

export type DeployedMarket = { stock: Address; vault: Address; router: Address; pieces: readonly Address[]; symbols: readonly string[] };

export const DEPLOYED = {
${marketSrc}
} as const satisfies Record<string, DeployedMarket>;

/** First block of the current deployment; event scans start here. */
export const DEPLOY_BLOCK = ${deployBlock}n;
`;
writeFileSync(join(root, "lib", "addresses.ts"), addr);

mkdirSync(join(root, "lib", "abis"), { recursive: true });
const names = { SegmentVault: "vaultAbi", SegmentRouter: "routerAbi", PieceToken: "pieceAbi", MockB20: "stockAbi", Faucet: "faucetAbi" };
for (const [name, exportName] of Object.entries(names)) {
  const abi = JSON.parse(readFileSync(join(out, `${name}.sol`, `${name}.json`), "utf8")).abi;
  writeFileSync(join(root, "lib", "abis", `${name}.ts`), `${header}export const ${exportName} = ${JSON.stringify(abi, null, 2)} as const;\n`);
}
console.log("[sync] wrote lib/addresses.ts for", markets.join(", "), "and", Object.keys(names).length, "ABIs");
